static float wrap_positive(float x,float period){return x-floorf(x/period)*period;}
/* Mirrored repeats meet at identical edge pixels, avoiding jumps when a layer wraps. */
static void scrolling_layer(SDL_Texture*t,float speed,float scale,int alpha,int clouds){
 int taps=clouds<=0&&speed>=200?(quality>=2?4:quality?2:1):1;
 for(int sample=0;sample<taps;sample++){float shutter=(taps==1?0:(float)(taps-1-sample)/(taps-1))*.35f*backgroundFrameDt*environment_rate();float clock=backgroundClock-shutter;
 float w=1114*scale,h=742*scale,a=sideBlend*PI*.5f,dx=-sinf(a)*clock*speed,dy=cosf(a)*clock*speed;
 float x=wrap_positive(dx,w)-w,y=72+wrap_positive(dy,h)-h;
 SDL_SetTextureAlphaMod(t,(Uint8)clamp(alpha/(sample+1),0,255));
 int col0=-1-(int)floorf(dx/w),row0=-1-(int)floorf(dy/h);
 /* Cover the viewport in unscaled layer coordinates, including altitude zoom.
    Culling against the original tile size could discard enlarged visible tiles. */
 float zoom=clouds<0?ground_scale(-clouds-1):1;
 int firstCol=(int)floorf((480-480/zoom-x)/w),lastCol=(int)ceilf((480+480/zoom-x)/w);
 int firstRow=(int)floorf((420-348/zoom-y)/h),lastRow=(int)ceilf((420+348/zoom-y)/h);
 for(int row=firstRow;row<lastRow;row++)for(int col=firstCol;col<lastCol;col++){
  SDL_FRect dest={480+(x+col*w-480)*zoom,420+(y+row*h-420)*zoom,w*zoom,h*zoom};if(dest.x>960||dest.y>768||dest.x+dest.w<0||dest.y+dest.h<72)continue;
  int flip=(((col+col0)&1)?SDL_FLIP_HORIZONTAL:0)|(((row+row0)&1)?SDL_FLIP_VERTICAL:0);
  SDL_RenderTextureRotated(renderer,t,0,&dest,0,0,(SDL_FlipMode)flip);
 }
 }
 (void)clouds;
}
static float earth_cloud_cover(void){static const float cover[6]={.25f,.85f,.45f,1,.65f,.3f};int beat=g.clock/400;float t=fminf(1,(g.clock%400)/100.0f);t=t*t*(3-2*t);return cover[(beat+5)%6]+(cover[beat%6]-cover[(beat+5)%6])*t;}
